/**
 * Ctrl+Shift+F command palette with a visual regex builder.
 *
 * Searches the links on the current page, the person's courses, and offers site and settings searches.
 *
 * @module     theme_material/palette
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('theme_material/palette', ['core/ajax'], function(Ajax) {
    var config = {};
    var s = {};
    var courses = null;
    var root = null;
    var state = {regex: true, ignoreCase: true, active: 0, results: []};
    var opener = null;

    var BLOCKS = [
        ['^', 'startswith'], ['$', 'endswith'], ['.*', 'anything'], ['\\d', 'digit'],
        ['[A-Za-z]', 'letter'], ['\\b', 'wordedge'], ['\\s', 'space'], ['+', 'oneormore'],
        ['?', 'optional'], ['|', 'either'], ['(', 'groupopen'], [')', 'groupclose']
    ];

    /**
     * Read a saved switch.
     *
     * @param {string} key
     * @param {boolean} fallback
     * @returns {boolean}
     */
    function load(key, fallback) {
        try {
            var v = window.localStorage.getItem('theme_material_' + key);
            return v === null ? fallback : v === '1';
        } catch (e) {
            return fallback;
        }
    }

    /**
     * Save a switch.
     *
     * @param {string} key
     * @param {boolean} value
     */
    function save(key, value) {
        try {
            window.localStorage.setItem('theme_material_' + key, value ? '1' : '0');
        } catch (e) {
            // Storage can be unavailable; the switch then lasts for this page only.
        }
    }

    /**
     * Build an element.
     *
     * @param {string} tag
     * @param {Object} attrs
     * @param {Array|string} [children]
     * @returns {HTMLElement}
     */
    function el(tag, attrs, children) {
        var node = document.createElement(tag);
        Object.keys(attrs || {}).forEach(function(k) {
            if (k === 'text') {
                node.textContent = attrs[k];
            } else if (k.indexOf('on') === 0) {
                node.addEventListener(k.substring(2), attrs[k]);
            } else {
                node.setAttribute(k, attrs[k]);
            }
        });
        [].concat(children || []).forEach(function(c) {
            node.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
        });
        return node;
    }

    /**
     * Links on the page worth jumping to.
     *
     * @returns {Array}
     */
    function pageLinks() {
        var seen = {};
        var out = [];
        var scopes = '.primary-navigation, .secondary-navigation, .courseindex, #page-header, .usermenu, ' +
            '.drawer, #region-main nav, .breadcrumb, .moremenu, #page-footer';
        document.querySelectorAll(scopes).forEach(function(scope) {
            scope.querySelectorAll('a[href]').forEach(function(a) {
                var label = (a.getAttribute('aria-label') || a.textContent || '').replace(/\s+/g, ' ').trim();
                var href = a.href;
                if (!label || !href || href.indexOf('javascript:') === 0 || href.slice(-1) === '#' || seen[href + label]) {
                    return;
                }
                seen[href + label] = true;
                out.push({kind: s.kindpage || 'Page', label: label, href: href, where: ''});
            });
        });
        return out;
    }

    /**
     * The person's courses, fetched once.
     *
     * @returns {Promise<Array>}
     */
    function myCourses() {
        if (courses || !config.loggedin) {
            return Promise.resolve(courses || []);
        }
        return Ajax.call([{
            methodname: 'core_course_get_enrolled_courses_by_timeline_classification',
            args: {classification: 'all', limit: 0, offset: 0, sort: 'fullname'}
        }])[0].then(function(r) {
            courses = (r.courses || []).map(function(c) {
                return {kind: s.kindcourse || 'Course', label: c.fullname, href: c.viewurl, where: c.coursecategory || ''};
            });
            return courses;
        }).catch(function() {
            courses = [];
            return courses;
        });
    }

    /**
     * Compile the current query.
     *
     * @param {string} q
     * @returns {{test: Function, re: RegExp|null, invalid: boolean}}
     */
    function matcher(q) {
        if (!q) {
            return {test: function() {
                return true;
            }, re: null, invalid: false};
        }
        if (state.regex) {
            try {
                var re = new RegExp(q, state.ignoreCase ? 'i' : '');
                return {test: function(t) {
                    return re.test(t);
                }, re: re, invalid: false};
            } catch (e) {
                return {test: function() {
                    return false;
                }, re: null, invalid: true};
            }
        }
        var needle = state.ignoreCase ? q.toLowerCase() : q;
        return {test: function(t) {
            return (state.ignoreCase ? t.toLowerCase() : t).indexOf(needle) !== -1;
        }, re: null, invalid: false};
    }

    /**
     * Label with the match highlighted.
     *
     * @param {string} label
     * @param {Object} m
     * @param {string} q
     * @returns {HTMLElement}
     */
    function highlight(label, m, q) {
        var span = el('span', {});
        var start = -1;
        var len = 0;
        if (m.re) {
            var found = label.match(m.re);
            if (found && found[0]) {
                start = found.index;
                len = found[0].length;
            }
        } else if (q) {
            start = (state.ignoreCase ? label.toLowerCase() : label).indexOf(state.ignoreCase ? q.toLowerCase() : q);
            len = q.length;
        }
        if (start < 0) {
            span.textContent = label;
            return span;
        }
        span.appendChild(document.createTextNode(label.slice(0, start)));
        span.appendChild(el('mark', {text: label.slice(start, start + len)}));
        span.appendChild(document.createTextNode(label.slice(start + len)));
        return span;
    }

    /**
     * Refresh the list.
     */
    function render() {
        var input = root.querySelector('.md-palette-field input');
        var q = input.value;
        var m = matcher(q);
        var status = root.querySelector('.md-regex-status');
        status.classList.toggle('is-invalid', m.invalid);
        tokens(q);
        myCourses().then(function(list) {
            var all = list.concat(pageLinks());
            var results = m.invalid ? [] : all.filter(function(r) {
                return m.test(r.label);
            }).slice(0, 60);
            if (q && !m.invalid) {
                if (config.coursesearch) {
                    results.push({kind: s.kindsearch || 'Search', label: (s.searchcourses || 'Search all courses for') + ' "' + q + '"',
                        href: config.coursesearch + '?search=' + encodeURIComponent(q), where: ''});
                }
                if (config.adminsearch) {
                    results.push({kind: s.kindsetting || 'Setting', label: (s.searchsettings || 'Search site settings for') + ' "' + q + '"',
                        href: config.adminsearch + '?query=' + encodeURIComponent(q), where: ''});
                }
            }
            state.results = results;
            state.active = Math.min(state.active, Math.max(0, results.length - 1));
            status.textContent = m.invalid ? (s.patternincomplete || 'Pattern is incomplete') :
                results.length + ' ' + (s.matches || 'matches');
            var ul = root.querySelector('.md-results');
            ul.textContent = '';
            results.forEach(function(r, i) {
                var a = el('a', {href: r.href, 'class': i === state.active ? 'is-active' : '', id: 'md-res-' + i, role: 'option',
                    'aria-selected': i === state.active ? 'true' : 'false'}, [
                    el('span', {'class': 'md-kind', text: r.kind}), highlight(r.label, m, q),
                    el('span', {'class': 'md-where', text: r.where || ''})
                ]);
                ul.appendChild(el('li', {role: 'presentation'}, [a]));
            });
            root.querySelector('.md-empty').hidden = results.length > 0;
            input.setAttribute('aria-activedescendant', results.length ? 'md-res-' + state.active : '');
            return null;
        }).catch(function() {
            return null;
        });
    }

    /**
     * Show the pattern as removable tokens.
     *
     * @param {string} q
     */
    function tokens(q) {
        var row = root.querySelector('.md-token-row');
        row.querySelectorAll('.md-token').forEach(function(t) {
            t.remove();
        });
        if (!state.regex || !q) {
            return;
        }
        var parts = q.match(/\\.|\[[^\]]*\]|\.\*|[\^$|()+?*]|[^\\[\^$|()+?*.]+|./g) || [];
        parts.forEach(function(part, index) {
            row.insertBefore(el('button', {type: 'button', 'class': 'md-token', title: s.removeblock || 'Remove',
                text: part, onclick: function() {
                    parts.splice(index, 1);
                    var input = root.querySelector('.md-palette-field input');
                    input.value = parts.join('');
                    render();
                    input.focus();
                }}), row.querySelector('.md-regex-status'));
        });
    }

    /**
     * Toggle button bound to a state key.
     *
     * @param {string} key
     * @param {string} label
     * @returns {HTMLElement}
     */
    function toggle(key, label) {
        var b = el('button', {type: 'button', 'class': 'md-chip', 'aria-pressed': state[key] ? 'true' : 'false', text: label,
            onclick: function() {
                state[key] = !state[key];
                save(key, state[key]);
                b.setAttribute('aria-pressed', state[key] ? 'true' : 'false');
                root.querySelector('.md-regex-blocks').hidden = !state.regex || !config.regexbuilder;
                render();
            }});
        return b;
    }

    /**
     * Build the dialog once.
     */
    function build() {
        var input = el('input', {type: 'text', role: 'combobox', 'aria-expanded': 'true', 'aria-controls': 'md-results',
            'aria-autocomplete': 'list', autocomplete: 'off', spellcheck: 'false',
            'aria-label': s.searchplaceholder || 'Search', placeholder: s.searchplaceholder || 'Search',
            oninput: function() {
                state.active = 0;
                render();
            }});
        var blocks = el('div', {'class': 'md-chip-row md-regex-blocks'});
        BLOCKS.forEach(function(b) {
            blocks.appendChild(el('button', {type: 'button', 'class': 'md-chip is-block', onclick: function() {
                input.value += b[0];
                render();
                input.focus();
            }}, [el('code', {text: b[0]}), s['block' + b[1]] || b[1]]));
        });
        blocks.hidden = !state.regex || !config.regexbuilder;
        root = el('div', {'class': 'md-palette', role: 'dialog', 'aria-modal': 'true', 'aria-label': s.search || 'Search'}, [
            el('div', {'class': 'md-palette-field'}, [
                el('span', {'aria-hidden': 'true', text: '⌕'}), input,
                el('kbd', {text: 'Ctrl Shift F'})
            ]),
            el('section', {'class': 'md-regex', 'aria-label': s.regexbuilder || 'Regex builder'}, [
                el('div', {'class': 'md-regex-head'}, [
                    el('h2', {text: s.regexbuilder || 'Regex builder'}),
                    el('div', {'class': 'md-chip-row'}, [
                        toggle('regex', s.useregex || 'Regex'),
                        toggle('ignoreCase', s.ignorecase || 'Ignore case'),
                        el('button', {type: 'button', 'class': 'md-chip', text: s.clear || 'Clear', onclick: function() {
                            input.value = '';
                            render();
                            input.focus();
                        }})
                    ])
                ]),
                blocks,
                el('div', {'class': 'md-chip-row md-token-row'}, [el('span', {'class': 'md-regex-status', 'aria-live': 'polite'})])
            ]),
            el('ul', {'class': 'md-results', id: 'md-results', role: 'listbox'}),
            el('p', {'class': 'md-empty', text: s.nomatch || 'No match.'})
        ]);
        root.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                close();
            } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                e.preventDefault();
                var n = state.results.length;
                if (n) {
                    state.active = (state.active + (e.key === 'ArrowDown' ? 1 : n - 1)) % n;
                    render();
                }
            } else if (e.key === 'Enter' && e.target === input) {
                var r = state.results[state.active];
                if (r) {
                    window.location.href = r.href;
                }
            } else if (e.key === 'Tab') {
                var focusables = root.querySelectorAll('input, button, a[href]');
                var first = focusables[0];
                var last = focusables[focusables.length - 1];
                if (e.shiftKey && document.activeElement === first) {
                    e.preventDefault();
                    last.focus();
                } else if (!e.shiftKey && document.activeElement === last) {
                    e.preventDefault();
                    first.focus();
                }
            }
        });
    }

    /**
     * Open the palette.
     *
     * @param {string} [query] Text to search for.
     */
    function open(query) {
        if (!root) {
            build();
        }
        if (typeof query === 'string' && query) {
            state.regex = false;
            root.querySelector('.md-palette-field input').value = query;
        }
        if (root.isConnected) {
            render();
            return;
        }
        opener = document.activeElement;
        var scrim = el('div', {'class': 'md-palette-scrim', onclick: close});
        document.body.appendChild(scrim);
        document.body.appendChild(root);
        var input = root.querySelector('.md-palette-field input');
        input.select();
        input.focus();
        render();
    }

    /**
     * Close the palette and return focus.
     */
    function close() {
        if (!root || !root.isConnected) {
            return;
        }
        root.remove();
        var scrim = document.querySelector('.md-palette-scrim');
        if (scrim) {
            scrim.remove();
        }
        if (opener && opener.focus) {
            opener.focus();
        }
    }

    /**
     * Add the search button to the top bar.
     */
    function trigger() {
        var host = document.querySelector('#usernavigation') || document.querySelector('.navbar .ms-auto') ||
            document.querySelector('.navbar');
        if (!host || host.querySelector('.md-palette-trigger')) {
            return;
        }
        var b = el('button', {type: 'button', 'class': 'md-palette-trigger', 'aria-keyshortcuts': 'Control+Shift+F',
            onclick: open}, [el('span', {'aria-hidden': 'true', text: '⌕'}), el('span', {'class': 'd-none d-md-inline',
            text: s.search || 'Search'}), el('kbd', {'class': 'd-none d-lg-inline', text: 'Ctrl Shift F'})]);
        host.insertBefore(b, host.firstChild);
    }

    return {
        /**
         * Start the palette.
         *
         * @param {Object} cfg
         */
        init: function(cfg) {
            config = cfg;
            s = cfg.strings || {};
            state.regex = load('regex', !!cfg.regexbuilder);
            state.ignoreCase = load('ignoreCase', true);
            trigger();
            document.addEventListener('keydown', function(e) {
                if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'F' || e.key === 'f')) {
                    e.preventDefault();
                    if (root && root.isConnected) {
                        close();
                    } else {
                        open();
                    }
                }
            });
        },
        open: function(query) {
            if (!config.commandpalette && config.commandpalette !== undefined) {
                return;
            }
            open(query);
        }
    };
});
